#!/usr/bin/env node
import { runSandPlaywrightMcpServer, SandPlaywrightSetupError } from "./server.js";
runSandPlaywrightMcpServer(process.argv.slice(2)).catch((error) => {
    if (error instanceof SandPlaywrightSetupError) {
        process.stderr.write(`sand-playwright-mcp setup_failed:${error.setupFailure}\n`);
    }
    process.stderr.write(`sand-playwright-mcp: ${error instanceof Error ? error.message : String(error)}\n`);
    process.exit(1);
});
